@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,500;0,600;0,700;1,500;1,600&display=swap');
:root{--ink:#f7ecdb;--muted:#c0ad98;--gold:#e8b978;--rust:#bf6849;--panel:rgba(29,24,24,.88);--line:rgba(239,207,166,.2)}
*{box-sizing:border-box}html,body{height:100%;margin:0;background:#21191a;color:var(--ink);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit}#game{position:relative;width:100%;height:100%;min-height:580px;overflow:hidden;background:linear-gradient(180deg,#c77b5c 0%,#ecb17b 48%,#674344 100%);isolation:isolate}#world{position:absolute;inset:0;width:100%;height:100%;z-index:-2;display:block}.scene-wash{position:absolute;inset:0;z-index:-1;background:linear-gradient(180deg,rgba(24,22,27,.24),transparent 30%,rgba(20,18,21,.14) 60%,rgba(18,16,19,.68));pointer-events:none}.grain{position:absolute;inset:-50%;z-index:5;pointer-events:none;opacity:.1;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.5'/%3E%3C/svg%3E");animation:grain .22s steps(2) infinite}@keyframes grain{0%{transform:translate(0,0)}50%{transform:translate(-1%,1%)}100%{transform:translate(1%,-1%)}}
.topbar{position:absolute;top:0;left:0;right:0;height:80px;padding:0 5.3%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,244,227,.13);z-index:6}.wordmark{display:flex;align-items:center;gap:12px;color:var(--ink);font-size:11px;letter-spacing:.2em;font-weight:700;text-decoration:none}.wordmark i{font-family:'Playfair Display';font-size:14px;color:var(--gold);font-weight:500}.brand-mark{font-size:20px;color:var(--gold)}.chapter-label{position:absolute;left:50%;transform:translateX(-50%);font-size:9px;letter-spacing:.19em;color:#e5d2bd;display:flex;align-items:center;gap:9px}.live-dot{height:5px;width:5px;border-radius:50%;background:#dfaa75;box-shadow:0 0 9px #dfaa75}.top-actions{display:flex;gap:10px}.icon-button{width:37px;height:37px;border:1px solid rgba(255,244,227,.28);background:rgba(35,26,25,.22);border-radius:50%;font-size:16px;cursor:pointer;transition:.2s}.icon-button:hover{background:rgba(232,185,120,.2);border-color:var(--gold)}
.intro{position:absolute;inset:80px 0 0;z-index:2;display:flex;align-items:center;padding:0 11.8%;pointer-events:none}.intro-copy{width:min(430px,50vw);pointer-events:auto;margin-top:-3vh}.eyebrow{font-size:9px;letter-spacing:.24em;color:#e9bf88;display:flex;align-items:center;gap:10px}.intro .eyebrow span{width:20px;height:1px;background:#d59669}.intro h1{font-family:'Playfair Display',serif;font-size:clamp(57px,7vw,92px);line-height:.98;font-weight:500;letter-spacing:-.055em;margin:28px 0 20px;text-shadow:0 3px 25px rgba(34,20,20,.18)}.intro h1 em{color:#f1bf84;font-weight:500}.intro-copy p{font-size:14px;line-height:1.75;color:#f0dfce;max-width:350px;margin:0 0 29px}.primary-button{background:#e5b678;color:#2f2220;border:0;border-radius:3px;padding:0 19px;height:51px;display:inline-flex;align-items:center;gap:40px;cursor:pointer;font-size:11px;font-weight:700;letter-spacing:.03em;box-shadow:0 7px 25px rgba(12,9,10,.2);transition:.2s}.primary-button:hover{background:#f4cd99;transform:translateY(-2px)}.primary-button b{font-size:18px;font-weight:400}.intro-note{font-size:9px;color:#dfcbb5;margin-top:27px;letter-spacing:.025em;display:flex;align-items:center;gap:9px}.intro-note span{color:var(--gold);font-size:14px}.intro-bottom{position:absolute;bottom:30px;left:5.3%;right:5.3%;display:flex;justify-content:space-between;font-size:8px;letter-spacing:.18em;color:#f0dbca;opacity:.75}.hidden{display:none!important}
.game-hud{position:absolute;z-index:3;top:103px;left:5.3%;right:5.3%;display:flex;justify-content:space-between;align-items:center}.location-pill{border:1px solid rgba(255,240,220,.25);background:rgba(29,23,22,.34);padding:10px 14px;border-radius:2px;letter-spacing:.13em;font-size:9px;display:flex;align-items:center;gap:9px;backdrop-filter:blur(8px)}.location-icon{color:var(--gold);font-size:15px}.progress-wrap{display:flex;align-items:center;gap:12px;font-size:8px;letter-spacing:.15em;color:#f2dec9}.progress-track{height:2px;width:82px;background:rgba(255,245,230,.26)}.progress-track i{height:100%;width:18%;display:block;background:var(--gold);transition:width .5s}.progress-wrap b{font-size:9px;font-weight:500}
.dialogue{position:absolute;z-index:3;bottom:5.6%;left:50%;transform:translateX(-50%);width:min(720px,72vw);padding:19px 30px 16px;background:linear-gradient(120deg,rgba(31,26,26,.94),rgba(40,31,29,.9));border:1px solid rgba(235,197,155,.22);box-shadow:0 18px 70px rgba(14,11,12,.32);backdrop-filter:blur(18px);border-radius:3px;animation:rise .45s ease both}@keyframes rise{from{opacity:0;transform:translate(-50%,14px)}to{opacity:1;transform:translate(-50%,0)}}.speaker-row{display:flex;align-items:center;gap:11px;justify-content:center}.speaker-line{height:1px;width:27px;background:rgba(224,175,124,.38)}.speaker-name{font-size:8px;color:#e6b980;letter-spacing:.2em}.dialogue h2{text-align:center;font-family:'Playfair Display',serif;font-size:25px;font-weight:500;margin:10px 0 6px;letter-spacing:-.015em}.dialogue p{text-align:center;font-size:12px;line-height:1.7;color:#d9c9b9;max-width:590px;margin:0 auto 15px}.choices{display:flex;flex-direction:column;gap:6px}.choice{width:100%;border:1px solid rgba(245,219,190,.18);background:rgba(255,255,255,.035);min-height:38px;text-align:left;padding:8px 13px;display:flex;align-items:center;gap:12px;cursor:pointer;color:#f3e5d5;font-size:11px;transition:.18s}.choice:hover{border-color:rgba(232,185,120,.75);background:rgba(232,185,120,.1);transform:translateX(3px)}.choice:disabled{opacity:.55;cursor:default}.choice-key{color:#d8a56c;font-size:9px;font-weight:700;border:1px solid rgba(216,165,108,.38);height:19px;width:19px;display:grid;place-items:center;flex:none}.dialogue-foot{display:flex;justify-content:space-between;align-items:center;padding-top:11px;color:#9e8d7f;font-size:8px;letter-spacing:.1em}.dialogue-foot kbd{font-family:inherit;border:1px solid #6f5c50;padding:2px 4px;color:#d4b28e;margin:0 2px}.continue-button{border:0;background:transparent;color:var(--gold);letter-spacing:.12em;font-size:9px;cursor:pointer}.continue-button b{font-size:15px;margin-left:6px}
.character-card{position:absolute;z-index:2;left:5.3%;bottom:7%;min-width:247px;display:flex;align-items:center;gap:12px;background:rgba(30,24,23,.78);border:1px solid rgba(241,209,171,.2);padding:11px 15px 11px 11px;backdrop-filter:blur(10px);box-shadow:0 10px 34px rgba(10,8,8,.2)}.character-avatar{width:43px;height:43px;border-radius:50%;background:linear-gradient(145deg,#c78461,#5a3636);border:1px solid #e3b67e;display:grid;place-items:center;font-family:'Playfair Display';font-size:23px;color:#f6d4a9}.character-role{font-size:7px;letter-spacing:.17em;color:#d7a977}.character-name{font-family:'Playfair Display';font-size:17px;margin-top:2px}.character-mood{font-size:7px;letter-spacing:.12em;color:#b9aa9a;margin-top:4px}.character-mood span{display:inline-block;width:5px;height:5px;background:#d99772;border-radius:50%;margin-right:5px}.affection{margin-left:7px;padding-left:13px;border-left:1px solid var(--line);display:flex;flex-direction:column;gap:5px}.affection>span{font-size:7px;letter-spacing:.14em;color:#bba993}.hearts{letter-spacing:2px;font-size:11px;color:#e9b778;white-space:nowrap}.toast{position:absolute;z-index:7;top:160px;left:50%;transform:translateX(-50%);background:rgba(29,24,23,.9);border:1px solid var(--line);padding:11px 16px;font-size:10px;letter-spacing:.03em;box-shadow:0 8px 25px #21191a66}.toast span:first-child{color:var(--gold);margin-right:8px}
.journal-backdrop{position:absolute;z-index:8;inset:0;background:rgba(10,8,9,.38)}.journal{position:absolute;z-index:9;right:0;top:0;bottom:0;width:min(400px,90vw);background:#241e1e;border-left:1px solid var(--line);padding:31px 30px;box-shadow:-20px 0 60px #0e0a0a55;animation:slide .3s ease}.journal.hidden{display:none}@keyframes slide{from{transform:translateX(30px);opacity:0}to{transform:none;opacity:1}}.journal-head{display:flex;justify-content:space-between;align-items:flex-start}.journal-head h2{font:500 27px 'Playfair Display';margin:7px 0 0}.journal .icon-button{font-size:21px}.journal-tabs{display:flex;gap:25px;border-bottom:1px solid var(--line);margin-top:27px}.tab{background:none;border:0;padding:0 0 11px;font-size:8px;letter-spacing:.15em;color:#9e8d7e;cursor:pointer}.tab.active{color:var(--gold);border-bottom:1px solid var(--gold)}.journal-content{padding-top:18px}.note-entry{padding:14px 0;border-bottom:1px solid rgba(239,207,166,.12)}.note-entry b{font:500 17px 'Playfair Display';display:block;margin-bottom:5px}.note-entry p{font-size:11px;line-height:1.65;color:#c5b6a8;margin:0}.journal-footer{position:absolute;bottom:28px;font-size:8px;letter-spacing:.15em;color:#947f6d}
.ending-overlay{position:absolute;z-index:10;inset:0;background:rgba(20,17,18,.68);display:grid;place-items:center;backdrop-filter:blur(6px)}.ending-card{width:min(490px,90vw);text-align:center;padding:45px 48px;background:linear-gradient(145deg,#302525,#211d1e);border:1px solid rgba(238,193,142,.3);box-shadow:0 24px 80px #08070888}.ending-star{font-size:24px;color:var(--gold);margin-bottom:20px}.ending-card .eyebrow{justify-content:center}.ending-card h2{font:500 37px 'Playfair Display';margin:17px 0 12px}.ending-card p{color:#cdbdaf;font-size:12px;line-height:1.8}.ending-summary{margin:23px auto 25px;padding:13px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);font-size:9px;letter-spacing:.12em;color:#e8bd8c}.ending-card .primary-button{justify-content:space-between;width:100%;margin-top:5px}.loading{position:absolute;z-index:20;inset:0;display:grid;place-content:center;justify-items:center;gap:14px;background:#21191a;color:#c8a47f;font-size:9px;letter-spacing:.24em;transition:opacity .5s}.loading.done{opacity:0;pointer-events:none}.loading-star{font-size:31px;animation:spin 4s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}
@media(max-width:700px){#game{min-height:600px}.topbar{height:65px;padding:0 18px}.wordmark{font-size:9px;gap:7px}.chapter-label{display:none}.intro{inset:65px 0 0;padding:0 8%;align-items:center}.intro-copy{width:90%;margin-top:-70px}.intro h1{font-size:64px;margin:22px 0 14px}.intro-copy p{font-size:12px;max-width:300px}.intro-note{font-size:8px;max-width:290px;line-height:1.5}.intro-bottom{left:18px;right:18px;bottom:18px;font-size:7px}.game-hud{top:80px;left:18px;right:18px}.location-pill{padding:8px 10px;font-size:8px}.progress-wrap{gap:7px;font-size:7px}.progress-track{width:35px}.dialogue{bottom:max(15px,env(safe-area-inset-bottom));width:calc(100% - 24px);padding:16px 15px 12px}.dialogue h2{font-size:22px;margin-top:8px}.dialogue p{font-size:11px;line-height:1.55;margin-bottom:11px}.choice{font-size:10px;min-height:39px;padding:8px}.dialogue-foot{font-size:7px}.character-card{left:12px;bottom:auto;top:137px;min-width:0;padding:8px 10px}.character-avatar{height:35px;width:35px;font-size:18px}.character-role{font-size:6px}.character-name{font-size:14px}.character-mood{font-size:6px}.affection{padding-left:8px;margin-left:0}.hearts{font-size:9px}.scene-wash{background:linear-gradient(180deg,rgba(24,22,27,.23),transparent 20%,rgba(20,18,21,.04) 38%,rgba(18,16,19,.82) 71%)}.toast{top:120px;width:max-content;max-width:90vw}.ending-card{padding:34px 25px}.ending-card h2{font-size:31px}}
@media(max-height:700px) and (min-width:701px){.dialogue{bottom:2.5%;padding-top:13px;padding-bottom:10px}.dialogue p{margin-bottom:9px}.choice{min-height:34px;padding:6px 12px}.intro h1{font-size:72px;margin:18px 0}.intro-copy{margin-top:-1vh}.character-card{bottom:3%}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const $ = (id) => document.getElementById(id);
const canvas = $('world');
let renderer, scene, camera, clock, town, player, dust = [], lanterns = [], heroine;
const routes = {
  ada: { name:'Ada Vale', role:'THE SALOON SINGER', glyph:'A', coat:0x81484a, hair:0x30202a, hat:0x33262b, mood:'A VOICE IN THE DARK', intro:'Ada Vale sings like she has a secret to sell—and somehow, every verse tonight seems meant for you.', date:'The saloon is nearly empty. Ada has saved you a table by the piano, where the lamplight turns her smile to honey.', conflict:'A folded note slips from Ada’s sleeve. She has been leaving one at your door every morning. Her eyes flick up, hopeful and afraid.',
    first:[['Ask what she really wants to say.','Her practiced smile softens. “Someone who listens. Someone I don’t have to sing for.”',1,'She lets the silence between you feel like a song, not a performance.'],['Tell her the serenades are getting a little intense.','Ada’s gaze drops. “I thought… I wanted you to know I was thinking of you.”',0,'She nods, listening instead of reaching for another verse.'],['Request a song, then keep your distance.','She sings a lovely, aching tune. When it ends, you thank her and step into the cool night.',-1,'The last note follows you outside. She does not.'] ],
    second:[['Tell her the notes feel like too much, and ask her to stop.','“I can do that,” Ada says. The hurt is real, but so is the relief in her honest answer.',0,'Ada tears the extra notes in half. “No more surprises. Just a hello, if you want one.”'],['Invite her to share a song on your terms.','You ask for one song, one evening, and no secret notes. Ada agrees—and keeps her word.',1,'She asks before taking your hand. You answer with a smile, and she sings just for you.'] ],
    close:'Ada leaves the door open, and finally leaves the choice with you.' },
  rosalie: { name:'Rosalie Finch', role:'THE FRONTIER DOCTOR', glyph:'R', coat:0x66745c, hair:0x4a2d24, hat:0x786146, mood:'NOTICING EVERYTHING', intro:'Dr. Rosalie Finch can diagnose a fever at twenty paces. She has also noticed every time you cross the street.', date:'Rosalie invites you to the clinic garden after hours. The desert sage is in bloom, and her careful composure is not.', conflict:'On the clinic desk: a map marked with your daily errands. Rosalie looks stricken when she sees you find it. “I told myself it was concern.”',
    first:[['Ask why she keeps finding reasons to check on you.','“Because I like you,” she says. “And I got it into my head that worry was the same as care.”',1,'She admits it plainly, without a medical excuse to hide behind.'],['Say you need room to breathe.','Rosalie closes the ledger. “You’re right. Caring about someone doesn’t make me entitled to their time.”',0,'She listens closely, the way a good doctor should.'],['Change the subject to her garden.','She brightens at the question, though her attention keeps wandering back to you.',-1,'You talk about sage and rain until the awkward moment passes.'] ],
    second:[['Ask her to put the map away and respect your privacy.','She feeds the map to the stove. “No more tracking. I’m sorry I confused vigilance with affection.”',0,'She promises the clinic—and your private life—will stay separate.'],['Suggest a proper date, with honest check-ins.','Rosalie asks what would make you comfortable. You agree to meet in town, with no more quiet investigations.',1,'She offers her arm, then waits for your answer. It is a small, lovely beginning.'] ],
    close:'Rosalie returns your trust to you, one honest choice at a time.' },
  june: { name:'June Calder', role:'THE TRAIN-ROBBING OUTLAW', glyph:'J', coat:0x75563a, hair:0x382a22, hat:0x3e3027, mood:'A DANGEROUS GRIN', intro:'June Calder is wanted in three counties. Her attention is flattering, her grin is trouble, and she is not good at subtle.', date:'At the edge of town, June has a blanket, a stolen bottle of lemonade, and a view of the sunset. She has also brought your favorite book.', conflict:'A horse waits saddled behind the livery. June plans to ride out with you before sunrise—without asking first. “I thought you’d want an adventure.”',
    first:[['Ask how she knew which book you liked.','“I asked the bookseller,” June admits. “I wanted to surprise you. Maybe I got carried away.”',1,'For once, her grin turns sheepish. You ask; she answers.'],['Tell her surprises are not the same as consent.','June’s bravado falters. “Fair. I should’ve asked. I’m better at making a getaway than a good impression.”',0,'She takes the lesson seriously, even if it pinches her pride.'],['Laugh it off and enjoy the sunset.','June spins a thrilling story about the law, the train, and her terrible aim with a lasso.',-1,'The story is fun. The uneasy feeling does not quite leave.'] ],
    second:[['Tell her you’re not leaving town unless you decide to.','June unbridles the horse. “Your call. I’m sorry I made it for you.”',0,'She stays right there, hands visible, and lets you choose the road.'],['Invite her to stay and take you on a real date tomorrow.','“Tomorrow, in town. No stolen horses, no vanishing acts,” June says. You hold her to it.',1,'She offers a hand. When you take it, she looks more surprised than if you’d drawn a gun.'] ],
    close:'June learns that the best getaway is one you choose together.' }
};

const state = { started:false, route:null, spark:0, stage:0, notes:[], ending:null, journalTab:'notes', ambience:true };
const names = { arrive:'MERCY · MAIN STREET', meet:'MERCY · MAIN STREET', date:'THE EDGE OF TOWN', truth:'A QUIET MOMENT', last:'THE CHOICE IS YOURS' };

function makeRenderer(){
  try { renderer = new THREE.WebGLRenderer({canvas,antialias:true,alpha:false}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.65)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.1; }
  catch(e){ $('loading').innerHTML='<span class="loading-star">✦</span><span>YOUR BROWSER COULD NOT OPEN THE FRONTIER</span>'; console.error(e); return false; }
  scene=new THREE.Scene(); scene.background=new THREE.Color(0xd38c6a); scene.fog=new THREE.Fog(0xc78269,18,70);
  camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,120); camera.position.set(0,5.6,14.5); camera.lookAt(0,1.6,-1);
  clock=new THREE.Clock();
  const hemi=new THREE.HemisphereLight(0xffdfbd,0x42343a,2.1); scene.add(hemi);
  const sun=new THREE.DirectionalLight(0xffce9d,3.3); sun.position.set(-5,10,5); sun.castShadow=true; sun.shadow.mapSize.set(1024,1024); scene.add(sun);
  const fill=new THREE.PointLight(0xf19a69,22,32); fill.position.set(2,5,-4); scene.add(fill);
  town=new THREE.Group(); scene.add(town); buildTown(); addDust();
  window.addEventListener('resize',resize); renderer.setAnimationLoop(render);
  return true;
}
function mat(color,roughness=.88){return new THREE.MeshStandardMaterial({color,roughness});}
function box(parent,x,y,z,sx,sy,sz,color,rot=0){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),mat(color));m.position.set(x,y,z);m.rotation.y=rot;m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function cone(parent,x,y,z,r,h,color,segments=4){const m=new THREE.Mesh(new THREE.ConeGeometry(r,h,segments),mat(color));m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m;}
function cylinder(parent,x,y,z,r1,r2,h,color,segments=8){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),mat(color));m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m;}
function buildBuilding(x,z,w,h,color,kind='flat'){
 const g=new THREE.Group();g.position.set(x,0,z);town.add(g);box(g,0,h/2,0,w,h,w*.72,color);
 if(kind==='saloon'||kind==='hotel'){const roof=box(g,0,h+.05,0,w+.3,.18,w*.8,0x3d2927); roof.position.y=h+.04;box(g,0,h-.3,w*.37,.56,.14,.08,0x452a27); for(let i=-1;i<=1;i++)box(g,i*w*.23,h*.4,w*.365,.08,h*.44,.06,0x392724);}
 else {const roof=cone(g,0,h+.23,0,w*.74,.52,0x60443a,4);roof.rotation.y=Math.PI/4;}
 for(let yy=1.2;yy<h-.45;yy+=1.3){for(let xx=-w*.28;xx<=w*.3;xx+=w*.55){box(g,xx,yy,w*.365,.48,.62,.08,0x382d2b);box(g,xx,yy,w*.415,.34,.45,.03,0xdda06c);}}
 // porch, posts and hand-painted sign
 box(g,0,.68,w*.61,w+.48,.12,.58,0x604333);for(let xx=-w*.42;xx<=w*.43;xx+=w*.84)cylinder(g,xx,.34,w*.78,.055,.065,.66,0x4a342d,6);
 if(kind==='saloon'){box(g,0,h+.48,w*.32,2.2,.46,.12,0x432c2a);}
 return g;
}
function buildTown(){
 const floor=new THREE.Mesh(new THREE.PlaneGeometry(120,120),mat(0x9c624b));floor.rotation.x=-Math.PI/2;floor.position.y=-.12;floor.receiveShadow=true;town.add(floor);
 // street and boardwalks
 box(town,0,-.045,0,6,.05,110,0x9a634c);box(town,-5,.03,0,2.5,.1,100,0x6a4839);box(town,5,.03,0,2.5,.1,100,0x6a4839);
 for(let z=-20;z<20;z+=2.2){box(town,0,.005,z,5.9,.012,.025,0xb87a58);}
 buildBuilding(-8,-5,5,5.4,0x9b6551,'saloon');buildBuilding(8,-7,4.4,4.6,0xc0a07c,'hotel');buildBuilding(-8,5,4.3,4.2,0xb58a66);buildBuilding(8,4,4.8,5,0x806454,'saloon');buildBuilding(-8,-15,4,4.1,0xc6a37b);buildBuilding(8,-16,4.5,4.4,0x9d6450);
 // distant mesas
 for(let i=0;i<8;i++){const m=new THREE.Mesh(new THREE.ConeGeometry(5+Math.random()*5,5+Math.random()*5,4),mat(i%2?0x985e57:0xa9695a));m.position.set(-30+i*9,2.3,-32-Math.random()*8);m.rotation.y=Math.PI/4;town.add(m);}
 // water tower and windmill silhouette
 cylinder(town,-14,3,-15,1.3,1.3,4,0x59443a,10);cylinder(town,-14,5.1,-15,1.55,1.55,.65,0x584139,10);cylinder(town,-14,5.7,-15,.08,.08,1.3,0x44332f,8);
 // hitching rails and barrel props
 for(const x of [-4.7,4.7]){box(town,x,.55,-4,.12,.12,4,0x53392f);box(town,x,.3,-5.7,.12,.12,4,0x53392f);}
 for(let i=0;i<7;i++){const x=(i%2?1:-1)*(6.3+Math.random()*2),z=-10+Math.random()*19;cylinder(town,x,.45,z,.36,.33,.9,0x694331,8);}
 // glowing street lamps
 for(const x of [-4.5,4.5])for(const z of [-10,2,12]){cylinder(town,x,1.9,z,.045,.055,3.8,0x49332d,6);box(town,x,3.85,z,.36,.4,.36,0x563a30);const lamp=new THREE.PointLight(0xffae6d,3,7);lamp.position.set(x,3.7,z);scene.add(lamp);lanterns.push(lamp);}
}
function addDust(){const geo=new THREE.BufferGeometry(),positions=new Float32Array(360*3);for(let i=0;i<360;i++){positions[i*3]=(Math.random()-.5)*35;positions[i*3+1]=Math.random()*7;positions[i*3+2]=(Math.random()-.5)*40-2;}geo.setAttribute('position',new THREE.BufferAttribute(positions,3));const pts=new THREE.Points(geo,new THREE.PointsMaterial({color:0xf5c38b,size:.045,transparent:true,opacity:.43,depthWrite:false}));scene.add(pts);dust.push(pts);}
function createHeroine(route){
 if(heroine){scene.remove(heroine);heroine=null;} if(!route)return;
 const c=routes[route],g=new THREE.Group();g.position.set(2.2,0,1.4);scene.add(g);heroine=g;
 // A stylized low-poly adult frontier woman, fully clothed
 const skin=mat(0xe4b28e),coat=mat(c.coat),hair=mat(c.hair),hat=mat(c.hat),dark=mat(0x332725),shirt=mat(0xe3c7a6);
 cylinder(g,0,1.05,0,.34,.48,1.25,c.coat,7);
 const torso=new THREE.Mesh(new THREE.CylinderGeometry(.34,.48,1.1,7),coat);torso.position.y=1.04;torso.castShadow=true;g.add(torso);
 // shirt front and neck
 cylinder(g,0,1.15,.275,.15,.22,.85,0xd7c19f,6);
 cylinder(g,1.02,1.1,0,.13,.16,.72,c.coat,6).rotation.z=-.12;cylinder(g,-1.02,1.1,0,.13,.16,.72,c.coat,6).rotation.z=.12;
 const head=new THREE.Mesh(new THREE.SphereGeometry(.34,9,7),skin);head.position.set(0,1.95,.02);head.scale.set(.88,1.13,.83);head.castShadow=true;g.add(head);
 const haircap=new THREE.Mesh(new THREE.SphereGeometry(.36,8,6,0,Math.PI*2,0,Math.PI*.63),hair);haircap.position.set(0,2.05,-.015);haircap.scale.set(1.02,1.12,.92);g.add(haircap);
 // hair falling on shoulders
 for(const side of [-1,1]){const lock=new THREE.Mesh(new THREE.CapsuleGeometry(.085,.62,3,5),hair);lock.position.set(side*.28,1.68,-.08);lock.rotation.z=side*-.12;g.add(lock);}
 // eyes / nose / smile details
 for(const x of [-.11,.11]){const eye=new THREE.Mesh(new THREE.SphereGeometry(.025,6,5),dark);eye.position.set(x,1.99,.306);g.add(eye);}
 const nose=new THREE.Mesh(new THREE.ConeGeometry(.045,.1,5),skin);nose.position.set(0,1.87,.32);nose.rotation.x=Math.PI/2;g.add(nose);
 // hat crown and brim
 cylinder(g,0,2.4,0,.29,.26,.4,hat,8);const brim=new THREE.Mesh(new THREE.CylinderGeometry(.57,.57,.07,10),hat);brim.position.y=2.57;brim.scale.z=.72;g.add(brim);
 // band, vest trim, buttons
 cylinder(g,0,2.38,0,.295,.295,.08,mat(0xc58a55),8);
 for(let y=.95;y>-.15;y-=.28){const b=new THREE.Mesh(new THREE.SphereGeometry(.035,5,4),mat(0xe9bd7b));b.position.set(.03,y,.36);g.add(b);}
 // legs / boots
 for(const side of [-1,1]){cylinder(g,side*.19,.12,0,.13,.15,.62,dark,6);box(g,side*.2,-.18,.08,.25,.18,.42,0x302320);}
 // pose one hand toward hip; stylized hair accessory
 const bandana=box(g,0,2.21,.06,.33,.09,.1,route==='june'?0x9b5b40:route==='rosalie'?0x77815c:0x9b5555);
 g.rotation.y=-.13;g.scale.setScalar(1.04);return g;
}
function resize(){if(!renderer)return;camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.65));}
function render(){if(!renderer)return;const t=clock.getElapsedTime();for(const p of dust){const a=p.geometry.attributes.position;for(let i=0;i<a.count;i++){a.array[i*3]+=.002;if(a.array[i*3]>18)a.array[i*3]=-18;a.array[i*3+1]+=Math.sin(t+i)*.0007;}a.needsUpdate=true;}if(heroine){heroine.position.y=Math.sin(t*1.6)*.025;heroine.rotation.y=-.13+Math.sin(t*.4)*.025;}for(let i=0;i<lanterns.length;i++)lanterns[i].intensity=2.6+Math.sin(t*2+i)*.3;renderer.render(scene,camera);}
if(makeRenderer())setTimeout(()=>{$('loading').classList.add('done');setTimeout(()=>$('loading').classList.add('hidden'),550);},500);

function logNote(title,text){state.notes.unshift({title,text});renderJournal();}
function showToast(text){$('toast-copy').textContent=text;$('toast').classList.remove('hidden');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>$('toast').classList.add('hidden'),2300);}
function moodText(){if(state.spark>=2)return'AN EASY HONESTY';if(state.spark<=-1)return'KEEPING HER DISTANCE';return routes[state.route]?.mood||'WATCHING THE STREET';}
function updateCard(){const r=routes[state.route];if(!r)return;$('character-card').classList.remove('hidden');$('character-name').textContent=r.name;$('character-role').textContent=r.role;$('avatar').textContent=r.glyph;$('character-mood').innerHTML=`<span></span> ${moodText()}`;$('hearts').textContent=Array.from({length:5},(_,i)=>i<Math.max(0,Math.min(5,state.spark+2))?'♥':'♡').join(' ');}
function setStage(stage,copy=''){
 state.stage=stage;const titles={arrive:'MERCY · FIRST NIGHT',meet:`MEETING ${routes[state.route].name.toUpperCase()}`,date:'AN EVENING TOGETHER',truth:'THE HONEST THING'};
 $('chapter-name').textContent=titles[stage]||'THE FIRST EVENING';$('location-name').textContent=stage==='date'?(state.route==='ada'?'MERCY · THE SALOON':state.route==='rosalie'?'THE CLINIC GARDEN':'THE LIVERY ROAD'):stage==='truth'?'MERCY · AFTER DARK':'MERCY · MAIN STREET';
 const progress=stage==='arrive'?16:stage==='meet'?38:stage==='date'?62:84;$('progress').style.width=progress+'%';$('progress-text').textContent=`0${Math.min(4,Math.max(1,['arrive','meet','date','truth'].indexOf(stage)+1))} / 04`;
 $('dialogue').classList.remove('hidden');$('continue-button').classList.add('hidden');
 if(stage==='arrive'){
   $('speaker').textContent='NARRATOR';$('dialogue-title').textContent='A town full of secrets';$('dialogue-copy').textContent='The train has left you in Mercy with one suitcase and a letter of introduction. The sun slips behind the mesas. From the saloon, a woman’s song follows you into the street.';
   $('character-card').classList.add('hidden');renderChoices([
    {text:'Follow the music to the saloon.',action:()=>selectRoute('ada')},
    {text:'Ask the doctor for directions—and stay for tea.',action:()=>selectRoute('rosalie')},
    {text:'Take the long way around, where the outlaws camp.',action:()=>selectRoute('june')}
   ]);
 }else if(stage==='meet'){
   const r=routes[state.route];$('speaker').textContent='NARRATOR';$('dialogue-title').textContent='A look that lingers';$('dialogue-copy').textContent=r.intro;
   renderChoices(r.first.map((c)=>({text:c[0],action:()=>{state.spark+=c[2];logNote('First impressions',c[1]);setStage('date');}})));
 }else if(stage==='date'){
   const r=routes[state.route];$('speaker').textContent=r.name.toUpperCase();$('dialogue-title').textContent='The part she doesn’t say';$('dialogue-copy').textContent=r.date+' '+r.conflict;
   renderChoices(r.second.map(c=>({text:c[0],action:()=>{state.spark+=c[2];logNote('A line in the sand',c[1]);setStage('truth');}})));
 }else if(stage==='truth'){
   const r=routes[state.route];$('speaker').textContent=r.name.toUpperCase();$('dialogue-title').textContent='What happens next is yours to choose';$('dialogue-copy').textContent=r.close+' She waits, hands folded, for your answer.';
   renderChoices([
    {text:'“I want to see where this goes—slowly, and honestly.”',action:()=>finish('romance')},
    {text:'“Let’s be friends. I need our boundaries to stay clear.”',action:()=>finish('friends')},
    {text:'“I’m riding on alone. Please don’t follow me.”',action:()=>finish('leave')}
   ]);
 }
 updateCard();
}
function renderChoices(items){const box=$('choices');box.innerHTML='';items.forEach((item,i)=>{const b=document.createElement('button');b.className='choice';b.innerHTML=`<span class="choice-key">${i+1}</span><span>${item.text}</span>`;b.addEventListener('click',()=>item.action());box.appendChild(b);});}
function selectRoute(route){state.route=route;state.spark=0;state.notes=[];state.started=true;createHeroine(route);$('intro').classList.add('hidden');$('game-hud').classList.remove('hidden');logNote('A new arrival','You stepped off the train in Mercy, New Mexico, with a whole life still unwritten.');setStage('meet');showToast(`You met ${routes[route].name}.`);}
function finish(kind){const r=routes[state.route];state.ending=kind;$('dialogue').classList.add('hidden');$('character-card').classList.add('hidden');$('ending-overlay').classList.remove('hidden');
 let title,copy;if(kind==='romance'){
  title=state.spark>=2?'A softer kind of wild':'A beginning, on your terms';copy=state.spark>=2?`${r.name} asks before taking your hand. You say yes. The two of you watch the last light fade over Mercy, with no promises except the ones you choose to make. Tomorrow can wait.`:`There is a spark between you, and room around it to breathe. ${r.name} agrees that this is a beginning—not a claim. Under the wide desert sky, that feels like enough.`;
  logNote('A beginning','You chose to explore a romance at your own pace, with honesty and mutual respect.');
 }else if(kind==='friends'){
  title='A friendship worth keeping';copy=`${r.name} is quiet for a moment, then nods. There is disappointment, but no argument. You part with a clear boundary and the possibility of a kinder friendship.`;logNote('A clear answer','You chose friendship and set a boundary. She accepted your answer.');
 }else{title='The open road';copy=`You leave Mercy before dawn. ${r.name} does not follow. The open road is uncertain, but it belongs to you—and that is its own kind of freedom.`;logNote('The open road','You chose to leave. Your next chapter is yours alone.');}
 $('ending-title').textContent=title;$('ending-copy').textContent=copy;$('ending-summary').textContent=`${r.name.toUpperCase()}  ·  ${kind==='romance'?'A SLOW-BURN ROMANCE':kind==='friends'?'A BOUNDARY RESPECTED':'A SOLO JOURNEY'}  ·  SPARK ${Math.max(0,state.spark+2)}/5`;
 $('chapter-name').textContent='THE END · FOR NOW';$('progress').style.width='100%';$('progress-text').textContent='04 / 04';
}
function renderJournal(){const content=$('journal-content');if(!content)return;document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===state.journalTab));if(state.journalTab==='cast'){
 content.innerHTML=Object.values(routes).map(r=>`<div class="note-entry"><b>${r.name}</b><p>${r.role.toLowerCase().replace(/^the /,'')} · ${r.intro}</p></div>`).join('');return;}
 content.innerHTML=state.notes.length?state.notes.map(n=>`<div class="note-entry"><b>${n.title}</b><p>${n.text}</p></div>`).join(''):'<div class="note-entry"><b>Your story starts here</b><p>Mercy is full of people with stories to tell. Yours is still waiting to be written.</p></div>';
}
function toggleJournal(open){const show=typeof open==='boolean'?open:$('journal').classList.contains('hidden');$('journal').classList.toggle('hidden',!show);$('journal-backdrop').classList.toggle('hidden',!show);if(show)renderJournal();}
$('begin').addEventListener('click',()=>{state.started=true;$('intro').classList.add('hidden');$('game-hud').classList.remove('hidden');setStage('arrive');});
$('restart').addEventListener('click',()=>{state.route=null;state.spark=0;state.stage=0;state.notes=[];state.ending=null;$('ending-overlay').classList.add('hidden');$('game-hud').classList.add('hidden');$('dialogue').classList.add('hidden');$('character-card').classList.add('hidden');$('intro').classList.remove('hidden');if(heroine){scene.remove(heroine);heroine=null;}$('chapter-name').textContent='THE FIRST EVENING';$('progress').style.width='16%';});
$('journal-toggle').addEventListener('click',()=>toggleJournal());$('journal-close').addEventListener('click',()=>toggleJournal(false));$('journal-backdrop').addEventListener('click',()=>toggleJournal(false));document.querySelectorAll('.tab').forEach(t=>t.addEventListener('click',()=>{state.journalTab=t.dataset.tab;renderJournal();}));
$('sound-toggle').addEventListener('click',()=>{state.ambience=!state.ambience;$('sound-toggle').style.color=state.ambience?'':'#bd8468';showToast(state.ambience?'Ambience on.':'Ambience off.');});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){toggleJournal(false);return;}if(e.key>='1'&&e.key<='3'&&!$('dialogue').classList.contains('hidden')){const b=$('choices').children[Number(e.key)-1];if(b)b.click();}});
renderJournal();

