import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';
const $ = (id) => document.getElementById(id);
const canvas = $('world');
let renderer, scene, camera, clock, town, dust = [], lanterns = [], heroine;
const routes = {
 ada:{name:'Ada Vale',role:'THE SALOON SINGER',glyph:'A',coat:0x81484a,hair:0x30202a,hat:0x33262b,mood:'A VOICE IN THE DARK',intro:'Ada Vale sings like she has a secret to sell—and somehow, every verse tonight seems meant for you.',date:'The saloon is nearly empty. Ada has saved you a table by the piano, where the lamplight turns her smile to honey.',conflict:'A folded note slips from Ada’s sleeve. She has been leaving one at your door every morning. Her eyes flick up, hopeful and afraid.',first:[['Ask what she really wants to say.','Her practiced smile softens. “Someone who listens. Someone I don’t have to sing for.”',1,'She lets the silence between you feel like a song, not a performance.'],['Tell her the serenades are getting a little intense.','Ada’s gaze drops. “I thought… I wanted you to know I was thinking of you.”',0,'She nods, listening instead of reaching for another verse.'],['Request a song, then keep your distance.','She sings a lovely, aching tune. When it ends, you thank her and step into the cool night.',-1,'The last note follows you outside. She does not.']],second:[['Tell her the notes feel like too much, and ask her to stop.','“I can do that,” Ada says. The hurt is real, but so is the relief in her honest answer.',0,'Ada tears the extra notes in half. “No more surprises. Just a hello, if you want one.”'],['Invite her to share a song on your terms.','You ask for one song, one evening, and no secret notes. Ada agrees—and keeps her word.',1,'She asks before taking your hand. You answer with a smile, and she sings just for you.']],close:'Ada leaves the door open, and finally leaves the choice with you.'},
 rosalie:{name:'Rosalie Finch',role:'THE FRONTIER DOCTOR',glyph:'R',coat:0x66745c,hair:0x4a2d24,hat:0x786146,mood:'NOTICING EVERYTHING',intro:'Dr. Rosalie Finch can diagnose a fever at twenty paces. She has also noticed every time you cross the street.',date:'Rosalie invites you to the clinic garden after hours. The desert sage is in bloom, and her careful composure is not.',conflict:'On the clinic desk: a map marked with your daily errands. Rosalie looks stricken when she sees you find it. “I told myself it was concern.”',first:[['Ask why she keeps finding reasons to check on you.','“Because I like you,” she says. “And I got it into my head that worry was the same as care.”',1,'She admits it plainly, without a medical excuse to hide behind.'],['Say you need room to breathe.','Rosalie closes the ledger. “You’re right. Caring about someone doesn’t make me entitled to their time.”',0,'She listens closely, the way a good doctor should.'],['Change the subject to her garden.','She brightens at the question, though her attention keeps wandering back to you.',-1,'You talk about sage and rain until the awkward moment passes.']],second:[['Ask her to put the map away and respect your privacy.','She feeds the map to the stove. “No more tracking. I’m sorry I confused vigilance with affection.”',0,'She promises the clinic—and your private life—will stay separate.'],['Suggest a proper date, with honest check-ins.','Rosalie asks what would make you comfortable. You agree to meet in town, with no more quiet investigations.',1,'She offers her arm, then waits for your answer. It is a small, lovely beginning.']],close:'Rosalie returns your trust to you, one honest choice at a time.'},
 june:{name:'June Calder',role:'THE TRAIN-ROBBING OUTLAW',glyph:'J',coat:0x75563a,hair:0x382a22,hat:0x3e3027,mood:'A DANGEROUS GRIN',intro:'June Calder is wanted in three counties. Her attention is flattering, her grin is trouble, and she is not good at subtle.',date:'At the edge of town, June has a blanket, a stolen bottle of lemonade, and a view of the sunset. She has also brought your favorite book.',conflict:'A horse waits saddled behind the livery. June plans to ride out with you before sunrise—without asking first. “I thought you’d want an adventure.”',first:[['Ask how she knew which book you liked.','“I asked the bookseller,” June admits. “I wanted to surprise you. Maybe I got carried away.”',1,'For once, her grin turns sheepish. You ask; she answers.'],['Tell her surprises are not the same as consent.','June’s bravado falters. “Fair. I should’ve asked. I’m better at making a getaway than a good impression.”',0,'She takes the lesson seriously, even if it pinches her pride.'],['Laugh it off and enjoy the sunset.','June spins a thrilling story about the law, the train, and her terrible aim with a lasso.',-1,'The story is fun. The uneasy feeling does not quite leave.']],second:[['Tell her you’re not leaving town unless you decide to.','June unbridles the horse. “Your call. I’m sorry I made it for you.”',0,'She stays right there, hands visible, and lets you choose the road.'],['Invite her to stay and take you on a real date tomorrow.','“Tomorrow, in town. No stolen horses, no vanishing acts,” June says. You hold her to it.',1,'She offers a hand. When you take it, she looks more surprised than if you’d drawn a gun.']],close:'June learns that the best getaway is one you choose together.'}
};
const state={started:false,route:null,spark:0,stage:0,notes:[],ending:null,journalTab:'notes',ambience:true};
function makeRenderer(){
 try{renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.65));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;}catch(e){$('loading').innerHTML='<span class="loading-star">✦</span><span>YOUR BROWSER COULD NOT OPEN THE FRONTIER</span>';console.error(e);return false;}
 scene=new THREE.Scene();scene.background=new THREE.Color(0xd38c6a);scene.fog=new THREE.Fog(0xc78269,18,70);camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,120);camera.position.set(0,5.6,14.5);camera.lookAt(0,1.6,-1);clock=new THREE.Clock();scene.add(new THREE.HemisphereLight(0xffdfbd,0x42343a,2.1));const sun=new THREE.DirectionalLight(0xffce9d,3.3);sun.position.set(-5,10,5);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);scene.add(sun);const fill=new THREE.PointLight(0xf19a69,22,32);fill.position.set(2,5,-4);scene.add(fill);town=new THREE.Group();scene.add(town);buildTown();addDust();window.addEventListener('resize',resize);renderer.setAnimationLoop(render);return true;
}
function mat(color,roughness=.88){return new THREE.MeshStandardMaterial({color,roughness});}
function box(parent,x,y,z,sx,sy,sz,color,rot=0){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),mat(color));m.position.set(x,y,z);m.rotation.y=rot;m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function cone(parent,x,y,z,r,h,color,segments=4){const m=new THREE.Mesh(new THREE.ConeGeometry(r,h,segments),mat(color));m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m;}
function cylinder(parent,x,y,z,r1,r2,h,color,segments=8){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),mat(color));m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m;}
function buildBuilding(x,z,w,h,color,kind='flat'){
 const g=new THREE.Group();g.position.set(x,0,z);town.add(g);box(g,0,h/2,0,w,h,w*.72,color);
