 if(heroine){scene.remove(heroine);heroine=null;}if(!route)return;const c=routes[route],g=new THREE.Group();g.position.set(2.2,0,1.4);scene.add(g);heroine=g;const skin=mat(0xe4b28e),coat=mat(c.coat),hair=mat(c.hair),hat=mat(c.hat),dark=mat(0x332725);
 const body=new THREE.Mesh(new THREE.CylinderGeometry(.34,.48,1.1,7),coat);body.position.y=1.04;body.castShadow=true;g.add(body);cylinder(g,0,1.15,.275,.15,.22,.85,0xd7c19f,6);cylinder(g,1.02,1.1,0,.13,.16,.72,c.coat,6).rotation.z=-.12;cylinder(g,-1.02,1.1,0,.13,.16,.72,c.coat,6).rotation.z=.12;
