 cylinder(g,0,2.4,0,.29,.26,.4,hat,8);const brim=new THREE.Mesh(new THREE.CylinderGeometry(.57,.57,.07,10),hat);brim.position.y=2.57;brim.scale.z=.72;g.add(brim);cylinder(g,0,2.38,0,.295,.295,.08,mat(0xc58a55),8);for(let y=.95;y>-.15;y-=.28){const b=new THREE.Mesh(new THREE.SphereGeometry(.035,5,4),mat(0xe9bd7b));b.position.set(.03,y,.36);g.add(b);}for(const side of [-1,1]){cylinder(g,side*.19,.12,0,.13,.15,.62,dark,6);box(g,side*.2,-.18,.08,.25,.18,.42,0x302320);}box(g,0,2.21,.06,.33,.09,.1,route==='june'?0x9b5b40:route==='rosalie'?0x77815c:0x9b5555);g.rotation.y=-.13;g.scale.setScalar(1.04);return g;
