function logNote(title,text){state.notes.unshift({title,text});renderJournal();}
function showToast(text){$('toast-copy').textContent=text;$('toast').classList.remove('hidden');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>$('toast').classList.add('hidden'),2300);}
function moodText(){if(state.spark>=2)return'AN EASY HONESTY';if(state.spark<=-1)return'KEEPING HER DISTANCE';return routes[state.route]?.mood||'WATCHING THE STREET';}
function updateCard(){const r=routes[state.route];if(!r)return;$('character-card').classList.remove('hidden');$('character-name').textContent=r.name;$('character-role').textContent=r.role;$('avatar').textContent=r.glyph;$('character-mood').innerHTML=`<span></span> ${moodText()}`;$('hearts').textContent=Array.from({length:5},(_,i)=>i<Math.max(0,Math.min(5,state.spark+2))?'♥':'♡').join(' ');}
function setStage(stage){
 state.stage=stage;const titles={arrive:'MERCY · FIRST NIGHT',meet:`MEETING ${routes[state.route].name.toUpperCase()}`,date:'AN EVENING TOGETHER',truth:'THE HONEST THING'};$('chapter-name').textContent=titles[stage]||'THE FIRST EVENING';$('location-name').textContent=stage==='date'?(state.route==='ada'?'MERCY · THE SALOON':state.route==='rosalie'?'THE CLINIC GARDEN':'THE LIVERY ROAD'):stage==='truth'?'MERCY · AFTER DARK':'MERCY · MAIN STREET';const p={arrive:16,meet:38,date:62,truth:84}[stage];$('progress').style.width=p+'%';$('progress-text').textContent=`0${['arrive','meet','date','truth'].indexOf(stage)+1} / 04`;$('dialogue').classList.remove('hidden');
 if(stage==='arrive'){$('speaker').textContent='NARRATOR';$('dialogue-title').textContent='A town full of secrets';$('dialogue-copy').textContent='The train has left you in Mercy with one suitcase and a letter of introduction. The sun slips behind the mesas. From the saloon, a woman’s song follows you into the street.';$('character-card').classList.add('hidden');renderChoices([{text:'Follow the music to the saloon.',action:()=>selectRoute('ada')},{text:'Ask the doctor for directions—and stay for tea.',action:()=>selectRoute('rosalie')},{text:'Take the long way around, where the outlaws camp.',action:()=>selectRoute('june')}]);}
 else if(stage==='meet'){const r=routes[state.route];$('speaker').textContent='NARRATOR';$('dialogue-title').textContent='A look that lingers';$('dialogue-copy').textContent=r.intro;renderChoices(r.first.map(c=>({text:c[0],action:()=>{state.spark+=c[2];logNote('First impressions',c[1]);setStage('date');}})));}
 else if(stage==='date'){const r=routes[state.route];$('speaker').textContent=r.name.toUpperCase();$('dialogue-title').textContent='The part she doesn’t say';$('dialogue-copy').textContent=r.date+' '+r.conflict;renderChoices(r.second.map(c=>({text:c[0],action:()=>{state.spark+=c[2];logNote('A line in the sand',c[1]);setStage('truth');}})));}
 else {const r=routes[state.route];$('speaker').textContent=r.name.toUpperCase();$('dialogue-title').textContent='What happens next is yours to choose';$('dialogue-copy').textContent=r.close+' She waits, hands folded, for your answer.';renderChoices([{text:'“I want to see where this goes—slowly, and honestly.”',action:()=>finish('romance')},{text:'“Let’s be friends. I need our boundaries to stay clear.”',action:()=>finish('friends')},{text:'“I’m riding on alone. Please don’t follow me.”',action:()=>finish('leave')}]);}updateCard();
}
function renderChoices(items){const box=$('choices');box.innerHTML='';items.forEach((item,i)=>{const b=document.createElement('button');b.className='choice';b.innerHTML=`<span class="choice-key">${i+1}</span><span>${item.text}</span>`;b.addEventListener('click',item.action);box.appendChild(b);});}
function selectRoute(route){state.route=route;state.spark=0;state.notes=[];state.started=true;createHeroine(route);$('intro').classList.add('hidden');$('game-hud').classList.remove('hidden');logNote('A new arrival','You stepped off the train in Mercy, New Mexico, with a whole life still unwritten.');setStage('meet');showToast(`You met ${routes[route].name}.`);}
function finish(kind){const r=routes[state.route];state.ending=kind;$('dialogue').classList.add('hidden');$('character-card').classList.add('hidden');$('ending-overlay').classList.remove('hidden');let title,copy;if(kind==='romance'){title=state.spark>=2?'A softer kind of wild':'A beginning, on your terms';copy=state.spark>=2?`${r.name} asks before taking your hand. You say yes. The two of you watch the last light fade over Mercy, with no promises except the ones you choose to make. Tomorrow can wait.`:`There is a spark between you, and room around it to breathe. ${r.name} agrees that this is a beginning—not a claim. Under the wide desert sky, that feels like enough.`;logNote('A beginning','You chose to explore a romance at your own pace, with honesty and mutual respect.');}else if(kind==='friends'){title='A friendship worth keeping';copy=`${r.name} is quiet for a moment, then nods. There is disappointment, but no argument. You part with a clear boundary and the possibility of a kinder friendship.`;logNote('A clear answer','You chose friendship and set a boundary. She accepted your answer.');}else{title='The open road';copy=`You leave Mercy before dawn. ${r.name} does not follow. The open road is uncertain, but it belongs to you—and that is its own kind of freedom.`;logNote('The open road','You chose to leave. Your next chapter is yours alone.');}$('ending-title').textContent=title;$('ending-copy').textContent=copy;$('ending-summary').textContent=`${r.name.toUpperCase()}  ·  ${kind==='romance'?'A SLOW-BURN ROMANCE':kind==='friends'?'A BOUNDARY RESPECTED':'A SOLO JOURNEY'}  ·  SPARK ${Math.max(0,state.spark+2)}/5`;$('chapter-name').textContent='THE END · FOR NOW';$('progress').style.width='100%';$('progress-text').textContent='04 / 04';}
function renderJournal(){const content=$('journal-content');if(!content)return;document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===state.journalTab));if(state.journalTab==='cast'){content.innerHTML=Object.values(routes).map(r=>`<div class="note-entry"><b>${r.name}</b><p>${r.role.toLowerCase().replace(/^the /,'')} · ${r.intro}</p></div>`).join('');return;}content.innerHTML=state.notes.length?state.notes.map(n=>`<div class="note-entry"><b>${n.title}</b><p>${n.text}</p></div>`).join(''):'<div class="note-entry"><b>Your story starts here</b><p>Mercy is full of people with stories to tell. Yours is still waiting to be written.</p></div>';}
function toggleJournal(open){const show=typeof open==='boolean'?open:$('journal').classList.contains('hidden');$('journal').classList.toggle('hidden',!show);$('journal-backdrop').classList.toggle('hidden',!show);if(show)renderJournal();}
$('begin').addEventListener('click',()=>{state.started=true;$('intro').classList.add('hidden');$('game-hud').classList.remove('hidden');setStage('arrive');});
$('restart').addEventListener('click',()=>{state.route=null;state.spark=0;state.stage=0;state.notes=[];state.ending=null;$('ending-overlay').classList.add('hidden');$('game-hud').classList.add('hidden');$('dialogue').classList.add('hidden');$('character-card').classList.add('hidden');$('intro').classList.remove('hidden');if(heroine){scene.remove(heroine);heroine=null;}$('chapter-name').textContent='THE FIRST EVENING';$('progress').style.width='16%';});
$('journal-toggle').addEventListener('click',()=>toggleJournal());$('journal-close').addEventListener('click',()=>toggleJournal(false));$('journal-backdrop').addEventListener('click',()=>toggleJournal(false));document.querySelectorAll('.tab').forEach(t=>t.addEventListener('click',()=>{state.journalTab=t.dataset.tab;renderJournal();}));$('sound-toggle').addEventListener('click',()=>{state.ambience=!state.ambience;$('sound-toggle').style.color=state.ambience?'':'#bd8468';showToast(state.ambience?'Ambience on.':'Ambience off.');});window.addEventListener('keydown',e=>{if(e.key==='Escape'){toggleJournal(false);return;}if(e.key>='1'&&e.key<='3'&&!$('dialogue').classList.contains('hidden')){const b=$('choices').children[Number(e.key)-1];if(b)b.click();}});renderJournal();

